from __future__ import annotations

import hashlib
import json
import os
import stat
from pathlib import Path

from .util import ToolError, run

MARKER = "generated by harness-style"
MANIFEST = "hooks.json"

PRE_COMMIT = """#!/bin/sh
# {marker} v1 —— 请勿手改（doctor 会校验 sha256，改了会报篡改）
# 只检查暂存区；不自动改文件（自动修复请显式执行 harness-style fix）
exec "{tool}" check --staged
""".format(marker=MARKER, tool="{tool}")

COMMIT_MSG = """#!/bin/sh
# {marker} v1 —— 请勿手改（doctor 会校验 sha256，改了会报篡改）
exec "{tool}" commit-msg "$1"
""".format(marker=MARKER, tool="{tool}")


def hooks_dir(root: Path) -> Path:
    return Path(root) / ".githooks"


def manifest_path(root: Path) -> Path:
    return Path(root) / ".harness-style" / MANIFEST


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _git_config_get(root: Path, key: str):
    rc, out, _ = run(["git", "config", "--local", "--get", key], cwd=root)
    return out.strip() if rc == 0 and out.strip() else None


def _git_config_set(root: Path, key: str, value: str):
    rc, out, err = run(["git", "config", "--local", key, value], cwd=root)
    if rc != 0:
        raise ToolError("git config 失败：{}".format((err or out).strip()))


def install(config, tool_path: Path, force: bool = False) -> list:
    root = Path(config.root)
    current = _git_config_get(root, "core.hooksPath")
    if current and current != ".githooks" and not force:
        raise ToolError(
            "core.hooksPath 已被设置为 {!r}；确认要接管请加 --force".format(current))

    directory = hooks_dir(root)
    directory.mkdir(parents=True, exist_ok=True)
    tool = str(Path(tool_path).resolve())

    written = []
    for name, template in (("pre-commit", PRE_COMMIT), ("commit-msg",
                                                        COMMIT_MSG)):
        path = directory / name
        path.write_text(template.replace("{tool}", tool), encoding="utf-8")
        path.chmod(path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP
                   | stat.S_IXOTH)
        written.append(path)

    _git_config_set(root, "core.hooksPath", ".githooks")

    manifest = manifest_path(root)
    manifest.parent.mkdir(parents=True, exist_ok=True)
    manifest.write_text(
        json.dumps(
            {
                "version": 1,
                "tool": tool,
                "files": {
                    path.name: sha256(path)
                    for path in written
                },
            },
            ensure_ascii=False,
            indent=2,
        ) + "\n",
        encoding="utf-8",
    )
    return [str(p) for p in written]


def uninstall(config) -> list:
    root = Path(config.root)
    removed = []
    for name in ("pre-commit", "commit-msg"):
        path = hooks_dir(root) / name
        if path.is_file() and MARKER in path.read_text(encoding="utf-8",
                                                       errors="replace"):
            path.unlink()
            removed.append(str(path))
    if _git_config_get(root, "core.hooksPath") == ".githooks":
        run(["git", "config", "--local", "--unset", "core.hooksPath"],
            cwd=root)
        removed.append("core.hooksPath")
    manifest = manifest_path(root)
    if manifest.is_file():
        manifest.unlink()
    return removed


def verify(config) -> list:
    """doctor 用：返回问题列表，空列表表示完好。"""
    root = Path(config.root)
    problems = []
    if _git_config_get(root, "core.hooksPath") != ".githooks":
        problems.append("core.hooksPath 未指向 .githooks（hook 未生效）")
        return problems

    manifest = manifest_path(root)
    if not manifest.is_file():
        problems.append("缺少 .harness-style/hooks.json，无法校验 hook 完整性")
        return problems
    try:
        data = json.loads(manifest.read_text(encoding="utf-8"))
        expected = data.get("files") or {}
    except ValueError:
        problems.append(".harness-style/hooks.json 损坏")
        return problems

    for name, digest in expected.items():
        path = hooks_dir(root) / name
        if not path.is_file():
            problems.append("hook 文件缺失：{}".format(path))
        elif sha256(path) != digest:
            problems.append("hook 被修改：{}（可能被篡改或手工改动）".format(name))
        elif not os.access(str(path), os.X_OK):
            problems.append("hook 不可执行：{}".format(name))
    return problems
